  const mode=explicit==='2d'?'2d':(explicit==='3d'||(Array.isArray(f.target)&&explicit!=='perspective'))?'3d':'perspective';
  const eventType=['Band / Live Performance','DJ / Stage','DJ / 360','Empty Stage'].includes(f.eventType)?f.eventType:'';
  const eventLayout=f.eventLayout&&Array.isArray(f.eventLayout.objects)?JSON.parse(JSON.stringify(f.eventLayout)):null;
  const extra=eventType&&eventLayout?{eventType,eventLayout}:{};
