function isDetailPaletteAssetRoot(root){
  const k=root&&root.userData&&root.userData.assetData&&root.userData.assetData.kind;
  return ['lightingConsole','soundConsole','djBooth','djBoothMonitor','djBoothSideSpeaker','visualLaptop','laptopScreen','guitar','bassGuitar','drumKit','micStand','wallMirror','sinkPair','doubleSinkCounter','speakerSub','speakerTop','speakerStack','stageFrontSubs','door','doorFrame','mothershipPortal','woodPanelFloor','brickWall','cementLeaner','woodPanelGate','longWoodBench','fineMeshWall'].includes(k)
}
function rebuildDetailPaletteAsset(root){
  if(!root||!root.userData||!root.userData.assetData)return false;
  const k=root.userData.assetData.kind;
  if(isSmokersAreaAssetKind(k)&&typeof rebuildSmokersAreaAssetObject==='function'){rebuildSmokersAreaAssetObject(root);return true}
  if(k==='lightingConsole'&&typeof rebuildLightingConsoleObject==='function'){rebuildLightingConsoleObject(root);return true}
  if(k==='wallMirror'&&typeof rebuildWallMirrorObject==='function'){rebuildWallMirrorObject(root);return true}
  if(k==='soundConsole'&&typeof rebuildSoundConsoleObject==='function'){rebuildSoundConsoleObject(root);return true}
  if(k==='djBooth'&&typeof rebuildDjBoothObject==='function'){rebuildDjBoothObject(root);return true}
  if(k==='djBoothMonitor'&&typeof rebuildDjBoothMonitorObject==='function'){rebuildDjBoothMonitorObject(root);return true}
  if(k==='djBoothSideSpeaker'&&typeof rebuildDjBoothSideSpeakerObject==='function'){rebuildDjBoothSideSpeakerObject(root);return true}
  if(['visualLaptop','laptopScreen','guitar','bassGuitar','drumKit','micStand'].includes(k)&&typeof rebuildStagePropObject==='function'){rebuildStagePropObject(root);return true}
  if(k==='sinkPair'&&typeof rebuildSinkPairObject==='function'){rebuildSinkPairObject(root);return true}
  if(k==='doubleSinkCounter'&&typeof rebuildDoubleSinkCounterObject==='function'){rebuildDoubleSinkCounterObject(root);return true}
  if(['speakerSub','speakerTop'].includes(k)&&typeof rebuildSpeakerCabinetObject==='function'){rebuildSpeakerCabinetObject(root);return true}
  if(k==='speakerStack'&&typeof rebuildSpeakerStackObject==='function'){rebuildSpeakerStackObject(root);return true}
  if(k==='stageFrontSubs'&&typeof rebuildStageFrontSubsObject==='function'){rebuildStageFrontSubsObject(root);return true}
  if(['door','doorFrame'].includes(k)&&typeof rebuildSimpleDoorObject==='function'){rebuildSimpleDoorObject(root);return true}
  if(k==='mothershipPortal'&&typeof rebuildMothershipPortalObject==='function'){rebuildMothershipPortalObject(root);return true}
  return false
}

function setObjectColour(root,hex){
  if(!root||root===traceGroup)return;
  root.userData.colorOverride=hex;
  // Detailed assets keep their internal colour palette. Only the main/base colour is allowed to change.
  // Rebuilding here also prevents resize / duplicate / reload from flattening every child mesh to one colour.
  if(isDetailPaletteAssetRoot(root)&&rebuildDetailPaletteAsset(root))return;
  if(root.userData.builderType==='barLeaner'){if(root.userData.leanerData)root.userData.leanerData.topColor=hex;if(typeof rebuildBarLeaner==='function')rebuildBarLeaner(root);return}
  if(isLedStripRoot(root)){const ld=getLedStripData(root);applyLedStripAppearance(root,hex,ld.brightness);return}
  if(typeof isSpeakerStackRoot==='function'&&isSpeakerStackRoot(root)){root.userData.colorOverride=hex;rebuildSpeakerStackObject(root);return}
  if(root.userData.floorBleedMesh&&root.userData.floorBleedMesh.material&&root.userData.floorBleedMesh.material.color)root.userData.floorBleedMesh.material.color.set(hex);
  if(root.userData.builderType==='sunsetLamp'){
    const c=new THREE.Color(hex);
    root.traverse(o=>{
      if(o.userData.sunsetGlow&&o.isMesh&&o.material){o.material.color.copy(c);if(o.material.emissive)o.material.emissive.copy(c)}
      if(o.userData.sunsetLight&&o.isLight)o.color.copy(c)
    });
    return;
  }
  root.traverse(o=>{if(o.isMesh)applyColourToMesh(o,hex)})
}
