function eventPresetRoots(){const pool=rawPresetPool(),metrics=presetStageMetrics(),sel=pool.filter(o=>isDjPresetRoot(o)||isBandGearPresetRoot(o)||isSpeakerLikePresetRoot(o)||rootPhysicallyOnMainStage(o,metrics));const gids=new Set(sel.map(o=>o.userData.groupId).filter(Boolean));pool.forEach(o=>{if(o.userData&&gids.has(o.userData.groupId)&&!sel.includes(o)&&o!==stage&&!isLightingRigLayerRoot(o))sel.push(o)});return sel}
function capacityPresetRoots(){const pool=rawPresetPool();return pool.filter(o=>o===stage||(o.userData&&o.userData.builderType==='furniture')||(+o.userData?.buildPhase||0)===5||(o.userData&&o.userData.builderType==='curtainRail')||(o.userData&&o.userData.builderType==='polyWall'&&o.userData.polyWallData&&o.userData.polyWallData.style==='curtain'))}
function lightingRigPresetRoots(){return rawPresetPool().filter(o=>isLightingRigLayerRoot(o))}
function captureRootTransformMap(roots){const out={};roots.forEach(o=>{if(!o||!o.userData||!o.userData.editId)return;const t=typeof worldAwareTransformState==='function'?worldAwareTransformState(o):{p:o.position.toArray(),r:[o.rotation.x,o.rotation.y,o.rotation.z,o.rotation.order],s:o.scale.toArray(),v:o.visible!==false};out[o.userData.editId]={p:t.p,r:t.r,s:t.s,v:t.v!==false}});return out}
function applyRootTransformMap(map,managedRoots,hideMissing=true){map=map||{};if(hideMissing)(managedRoots||[]).forEach(o=>{if(o&&o.userData&&!Object.prototype.hasOwnProperty.call(map,o.userData.editId))o.visible=false});Object.entries(map).forEach(([id,d])=>{const o=objectByEditId(id);if(!o||!d||!Array.isArray(d.p))return;o.position.fromArray(d.p);const r=d.r||[0,0,0,'XYZ'];o.rotation.set(r[0]||0,r[1]||0,r[2]||0,r[3]||'XYZ');o.scale.fromArray(d.s||[1,1,1]);o.visible=d.v!==false})}
function combinedPresetKey(eventType,capacity){return String(eventType||'Band')+'::'+String(capacity||'Small Cap')}
function captureLayoutPresetSceneState(eventType=null,capacity=null){eventType=eventType||document.getElementById('layoutEventType')?.value||'Band';capacity=capacity||document.getElementById('layoutCapacity')?.value||'Small Cap';return {version:4,eventType,capacity,event: captureRootTransformMap(eventPresetRoots()),capacityObjects:captureRootTransformMap(capacityPresetRoots()),lightingObjects:captureRootTransformMap(lightingRigPresetRoots()),lighting:(typeof capturePerformanceLightingState==='function'?capturePerformanceLightingState():null),barLights:(typeof barLightsEnabled!=='undefined'?!!barLightsEnabled:false),smokingArea:smokeFloor?smokeFloor.visible!==false:true,visualLoop:(typeof visualLoopMode!=='undefined'?visualLoopMode:'cycle')}}
function applyLayoutPresetSceneState(preset,{save=false,push=false,announce=''}={}){if(!preset||+preset.version<4)return false;const reoff=typeof editLightsOff!=='undefined'&&editLightsOff&&typeof applyEditLightsOff==='function';if(reoff)applyEditLightsOff(false);if(activeGroupId&&typeof releaseActiveGroupPivot==='function')releaseActiveGroupPivot(true);if(typeof clearMultiSelectionVisuals==='function')clearMultiSelectionVisuals();if(push)pushHistory();applyRootTransformMap(preset.event,eventPresetRoots(),true);applyRootTransformMap(preset.capacityObjects,capacityPresetRoots(),true);applyRootTransformMap(preset.lightingObjects,lightingRigPresetRoots(),false);if(preset.lighting&&typeof applyPerformanceLightingState==='function')applyPerformanceLightingState(preset.lighting);if(typeof applyBarLightsEnabled==='function')applyBarLightsEnabled(!!preset.barLights);if(smokeFloor)smokeFloor.visible=preset.smokingArea!==false;if(typeof applyVisualLoopSelection==='function')applyVisualLoopSelection(preset.visualLoop||'cycle');if(reoff)applyEditLightsOff(true);normaliseFunctionalLayerParents();normaliseCeilingMountedDetails();updateSelectionBox();if(save)saveLocalEditState(false);if(announce)flashEditor(announce);markRenderDirty(450);return true}
function saveNamedLayoutPreset(){const ev=document.getElementById('layoutEventType')?.value||'Band',cap=document.getElementById('layoutCapacity')?.value||'Small Cap',key=combinedPresetKey(ev,cap);layoutPresets[key]=captureLayoutPresetSceneState(ev,cap);activeCombinedPresetKey=key;activePromoterLayout=key;saveLocalEditState(false);syncLayoutPresetUI();flashEditor(ev+' + '+cap+' saved')}
function loadNamedLayoutPreset(key=null,opts={}){if(!key){const ev=document.getElementById('layoutEventType')?.value||'Band',cap=document.getElementById('layoutCapacity')?.value||'Small Cap';key=combinedPresetKey(ev,cap)}const p=layoutPresets[key];if(!p||+p.version<4){if(!opts.silent)flashEditor('No saved '+key.replace('::',' + ')+' preset yet');return false}const ok=applyLayoutPresetSceneState(p,{save:opts.preview!==true,push:opts.preview!==true,announce:opts.silent?'':key.replace('::',' + ')+' loaded'});if(ok){activeCombinedPresetKey=key;activePromoterLayout=key;syncLayoutPresetUI()}return ok}
