function syncLayoutPresetUI(){const ev=document.getElementById('layoutEventType'),cap=document.getElementById('layoutCapacity'),status=document.getElementById('layoutPresetStatus'),load=document.getElementById('loadCurrentLayoutPreset'),perf=document.getElementById('perfCombinedPreset'),key=combinedPresetKey(ev?.value||'Band',cap?.value||'Small Cap'),saved=!!(layoutPresets[key]&&+layoutPresets[key].version>=4);if(status){status.textContent=saved?key.replace('::',' + ')+' · SAVED':'NOT SAVED · arrange this event + capacity combination, then SAVE';status.classList.toggle('saved',saved)}if(load)load.disabled=!saved;if(perf){const current=perf.value,keys=savedCombinedPresetKeys();perf.innerHTML='<option value="">— CHOOSE SAVED PRESET —</option>'+keys.map(k=>'<option value="'+k.replace(/"/g,'&quot;')+'">'+k.replace('::',' · ')+'</option>').join('');perf.value=keys.includes(activeCombinedPresetKey)?activeCombinedPresetKey:(keys.includes(current)?current:'')}}
