/* trace reference image — local upload, opacity and alignment */
function setTraceStatus(msg,on=false){const el=document.getElementById('traceStatus');if(!el)return;el.textContent=msg;el.classList.toggle('on',on)}
function traceOpacityValue(){return Math.max(.05,Math.min(1,(+document.getElementById('traceOpacity').value||40)/100))}
function updateTraceOpacity(){const v=traceOpacityValue();document.getElementById('traceOpacityValue').textContent=Math.round(v*100)+'%';if(traceMesh&&traceMesh.material)traceMesh.material.opacity=v;saveLocalEditState(false)}
function syncTraceSizeInputs(){const w=document.getElementById('traceWidth'),h=document.getElementById('traceHeight');if(!w||!h)return;w.value=Math.abs(traceGroup.scale.x).toFixed(2);h.value=Math.abs(traceGroup.scale.z).toFixed(2)}
function updateTraceControlState(){
  const pin=document.getElementById('tracePin'),ratio=document.getElementById('traceAspectLock');
  if(pin){pin.textContent=tracePinned?'UNPIN IMAGE':'PIN IMAGE';pin.classList.toggle('pinned',tracePinned)}
  if(ratio){ratio.textContent=traceRatioLocked?'RATIO LOCKED':'FREE RATIO';ratio.classList.toggle('active',traceRatioLocked);ratio.disabled=tracePinned}
  ['traceEdit','traceFit','traceRotate90','traceWidth','traceHeight'].forEach(id=>{const el=document.getElementById(id);if(el)el.disabled=tracePinned});
  setTraceStatus(traceMesh?(tracePinned?'IMAGE PINNED':'IMAGE LOADED'):'NO IMAGE',!!traceMesh)
}
function setTraceSize(axis,value){
  if(!traceMesh||tracePinned)return;
  const v=Math.max(.1,Number(value)||.1);
  if(axis==='w'){
    traceGroup.scale.x=v;
    if(traceRatioLocked)traceGroup.scale.z=v/Math.max(traceAspect,.0001);
  }else{
    traceGroup.scale.z=v;
    if(traceRatioLocked)traceGroup.scale.x=v*Math.max(traceAspect,.0001);
  }
  syncTraceSizeInputs();updateSelectionBox();updateEditorSelected();saveLocalEditState(false)
}
function toggleTraceRatio(){if(tracePinned)return;traceRatioLocked=!traceRatioLocked;updateTraceControlState();saveLocalEditState(false)}
function toggleTracePin(){
  if(!traceMesh){flashEditor('Upload a reference image first');return}
  tracePinned=!tracePinned;traceGroup.userData.pinned=tracePinned;
  if(tracePinned&&selectedEdit===traceGroup)deselectEdit();
  updateTraceControlState();saveLocalEditState(false);flashEditor(tracePinned?'Reference image pinned':'Reference image unlocked')
}
function disposeTraceMesh(){if(!traceMesh)return;if(traceMesh.geometry)traceMesh.geometry.dispose();if(traceMesh.material){if(traceMesh.material.map)traceMesh.material.map.dispose();traceMesh.material.dispose()}traceGroup.remove(traceMesh);traceMesh=null}
function fitTraceToPlan(){if(!traceMesh||tracePinned)return;const bb=new THREE.Box3().setFromObject(exteriorFloor),size=new THREE.Vector3(),center=new THREE.Vector3();bb.getSize(size);bb.getCenter(center);const planAspect=size.x/Math.max(size.z,.001);let w,d;if(traceAspect>=planAspect){w=size.x;d=w/traceAspect}else{d=size.z;w=d*traceAspect}traceGroup.position.set(center.x,.015,center.z);traceGroup.rotation.set(0,0,0);traceGroup.scale.set(w,1,d);syncTraceSizeInputs();updateSelectionBox();updateEditorSelected();saveLocalEditState(false)}
function installTraceImage(dataURL,fit=true,state=null){
  const img=new Image();
  img.onload=()=>{disposeTraceMesh();traceDataURL=dataURL;traceAspect=img.naturalWidth/Math.max(img.naturalHeight,1);const tex=new THREE.Texture(img);tex.needsUpdate=true;tex.encoding=THREE.sRGBEncoding;const mat=new THREE.MeshBasicMaterial({map:tex,transparent:true,opacity:traceOpacityValue(),side:THREE.DoubleSide,depthWrite:false,toneMapped:false});traceMesh=new THREE.Mesh(new THREE.PlaneGeometry(1,1),mat);traceMesh.rotation.x=-Math.PI/2;traceMesh.renderOrder=-5;traceGroup.add(traceMesh);traceGroup.visible=true;traceLoaded=true;tracePinned=!!(state&&state.pin);traceRatioLocked=state&&state.ar===false?false:true;traceGroup.userData.pinned=tracePinned;if(state){traceGroup.position.fromArray(state.p||[0,.015,0]);const r=state.r||[0,0,0,'XYZ'];traceGroup.rotation.set(r[0],r[1],r[2],r[3]||'XYZ');traceGroup.scale.fromArray(state.s||[10,1,10]);traceGroup.visible=state.v!==false;const op=Math.round((state.o==null ? .4 : state.o)*100);document.getElementById('traceOpacity').value=op;mat.opacity=op/100}else if(fit)fitTraceToPlan();document.getElementById('layerTrace').checked=traceGroup.visible;document.getElementById('traceToggle').textContent=traceGroup.visible?'HIDE IMAGE':'SHOW IMAGE';document.getElementById('traceOpacityValue').textContent=Math.round(mat.opacity*100)+'%';syncTraceSizeInputs();updateTraceControlState()};
  img.onerror=()=>{setTraceStatus('IMAGE ERROR');flashEditor('Use JPG, PNG or WEBP')};
  img.src=dataURL;
}
function compressTraceFile(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const img=new Image();img.onerror=reject;img.onload=()=>{const maxSide=2200,ratio=Math.min(1,maxSide/Math.max(img.naturalWidth,img.naturalHeight));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.naturalWidth*ratio));c.height=Math.max(1,Math.round(img.naturalHeight*ratio));const ctx=c.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.9))};img.src=reader.result};reader.readAsDataURL(file)})}
function captureTraceState(){if(!traceDataURL||!traceMesh)return null;return {data:traceDataURL,p:traceGroup.position.toArray(),r:[traceGroup.rotation.x,traceGroup.rotation.y,traceGroup.rotation.z,traceGroup.rotation.order],s:traceGroup.scale.toArray(),v:traceGroup.visible!==false,o:traceMesh.material.opacity,pin:tracePinned,ar:traceRatioLocked}}
function applyTraceState(state){if(!state||!state.data)return;installTraceImage(state.data,false,state)}
function clearTraceImage(){if(selectedEdit===traceGroup)deselectEdit();disposeTraceMesh();traceDataURL=null;traceLoaded=false;tracePinned=false;traceRatioLocked=true;traceGroup.userData.pinned=false;traceGroup.visible=false;try{localStorage.removeItem('mothershipFloorplanTraceStateV1')}catch(e){}}
function selectTraceForEdit(){if(!traceMesh){flashEditor('Upload a reference image first');return}if(tracePinned){flashEditor('Unpin the image to edit it');return}if(!mode2d)setMode(true);traceGroup.visible=true;document.getElementById('layerTrace').checked=true;selectEdit(traceGroup);setEditTool('translate')}
function rotateTrace90(){if(!traceMesh||tracePinned)return;traceGroup.rotation.y+=Math.PI/2;updateSelectionBox();updateEditorSelected();saveLocalEditState(false)}
function toggleTrace(){if(!traceMesh)return;traceGroup.visible=!traceGroup.visible;document.getElementById('layerTrace').checked=traceGroup.visible;document.getElementById('traceToggle').textContent=traceGroup.visible?'HIDE IMAGE':'SHOW IMAGE';if(!traceGroup.visible&&selectedEdit===traceGroup)deselectEdit();saveLocalEditState(false)}

