let editMode=false,selectedEdit=null,editModeName='translate',editorRoots=[],staticEditorRoots=[],builderObjects=[],barDetailRoots=[],initialEditState=null,history=[],redoHistory=[]; let referenceUIBusy=false,layoutLocked=true,attachPickMode=false,autoSurfaceSnapEnabled=false,autoMainFloorLock=true,roomFloorEditView='normal',roomFloorNormalPreview=false;
let builderCounter=0,autoSnapEnabled=false,wallLinks=[],drawMode=null,drawPoints=[],activeTraceWall=null,activeTraceRamp=null,vertexEditMode=false,activeVertexIndex=-1,dragVertex=null,suppressNextCanvasClick=false,wallAlignSuggestion=null,copyBuffer=null,pointConnectMode=false,pointConnectFirst=-1,connectWallPickMode=false,connectWallSourceIndex=-1,roomCloserMode=false,wallTraceStartSnapped=false;
