function disposeObject3D(root){root.traverse(o=>{if(o.geometry)o.geometry.dispose()})}
function rootVisibleMaterial(root){
  if(root===exteriorFloor||root===smokeFloor)return false;
  let visible=false;root.traverse(o=>{if(o.isMesh){const m=o.material;if(!m||!m.transparent||m.opacity>.05)visible=true}});return visible
}
function classifyEditorRoot(root,counters){
  if(root===stage)return 'Stage'; if(root===upperBar)return 'Upper Bar'; if(root===lowerBar)return 'Lower Bar';
  if(root===foh)return 'FOH Booth'; if(root===merch)return 'Merch / Coat Check'; if(root===leftPlatform)return 'Left Raised Platform'; if(root===rightPlatform)return 'Right Raised Platform';
  if(root.isMesh&&root.geometry&&root.geometry.parameters){const p=root.geometry.parameters,w=+p.width||0,h=+p.height||0,d=+p.depth||0;if(h>2&&w<1&&d<1&&Math.abs(w-d)<.18)return 'Pillar '+String(++counters.pillar).padStart(2,'0');if(h>2&&Math.min(w,d)<.28)return 'Wall '+String(++counters.wall).padStart(2,'0')}
  return 'Object '+String(++counters.object).padStart(2,'0')
}
function rectPlanFootprint(x1,y1,x2,y2){return [[x1,y1],[x2,y1],[x2,y2],[x1,y2]].map(([x,y])=>p2w(x,y))}
function stagePlanFootprint(){
  const start=p2w(105,612),a=p2w(350,612),bend=p2w(440,705),c=p2w(545,612),out=[start,a];
  const c1=[a[0],bend[1]],c2=[c[0],bend[1]];
  for(let i=1;i<=5;i++){const t=i/5,u=1-t;out.push([u*u*u*a[0]+3*u*u*t*c1[0]+3*u*t*t*c2[0]+t*t*t*c[0],u*u*u*a[1]+3*u*u*t*c1[1]+3*u*t*t*c2[1]+t*t*t*c[1]])}
  out.push(p2w(470,1095),p2w(158,1095));return out
}
function markStaticPointSolid(root,points,role){if(!root)return;root.updateMatrixWorld(true);const b=new THREE.Box3().setFromObject(root);root.userData.staticSolidEdit={points:points.map(p=>[+p[0],+p[1]]),baseMatrix:root.matrixWorld.toArray(),baseY:b.min.y,role:role||'solid'}}
function markStaticPointSolids(){markStaticPointSolid(stage,stagePlanFootprint(),'stage');markStaticPointSolid(upperBar,rectPlanFootprint(1100,610,1625,810),'bar');markStaticPointSolid(lowerBar,rectPlanFootprint(625,1270,960,1420),'bar');markStaticPointSolid(foh,[[930,610],[1100,610],[1100,810],[1068,810],[930,650]].map(([x,y])=>p2w(x,y)),'foh');markStaticPointSolid(merch,rectPlanFootprint(1785,900,1985,1090),'counter')}
function buildEditorRoots(){
  const counters={wall:0,pillar:0,object:0};
  staticEditorRoots=[...venue.children,...structuralWallLayer.children].filter(root=>rootVisibleMaterial(root));
  staticEditorRoots.forEach((root,i)=>{root.userData.editId='edit_'+String(i+1).padStart(3,'0');root.userData.editName=classifyEditorRoot(root,counters);root.userData.lockedBase=true;if(root===leftPlatform||root===rightPlatform)root.userData.builderType='platformBox';else if(root.userData.editName.startsWith('Wall '))root.userData.builderType='wall';else if(root.userData.editName.startsWith('Pillar '))root.userData.builderType='pillar';else root.userData.builderType=root.userData.builderType||'object'});
  [[exteriorFloor,'surface_main_floor','Main Floor'],[smokeFloor,'surface_smoke_floor','Smoking Area Floor']].forEach(([root,id,name])=>{root.userData.editId=id;root.userData.editName=name;root.userData.builderType='floorSurface';root.userData.lockedBase=true;if(!staticEditorRoots.includes(root))staticEditorRoots.push(root)});[exteriorFloor,smokeFloor].forEach(syncFloorBleed);
  editorRoots=[...staticEditorRoots];markStaticPointSolids()
}
function nextBuilderId(){builderCounter++;return 'dyn_'+String(builderCounter).padStart(4,'0')}
function ceilingMountReferenceY(){try{return Math.max(2.10,+venueCalibrationDerived().roomCeiling||2.58)}catch(e){return 2.58}}
function isCeilingMountedFixtureKind(kind){return ['acUnit','ledPar','intimidator','movingMirrorScanner','strobeFixture','downlightFixture','ceilingTubeLight','ceilingLightPole'].includes(kind)}
function isCeilingDetailRoot(root){if(!root||!root.userData)return false;const type=root.userData.builderType||'',asset=root.userData.assetData||{},solid=root.userData.solidData||{},kind=asset.kind||'',name=String(root.userData.editName||'').toLowerCase(),item=String(root.userData.buildItem||'').toLowerCase(),cat=String(root.userData.buildCategory||'').toLowerCase();if(isCurtainTrackRoot(root)||type==='curtainRail')return true;if(type==='fixtureAsset'&&kind==='acUnit')return true;if(type==='solidPolygon'&&(solid.role==='ceilingBeam'||cat.includes('ceiling')||name.includes('ac unit')||item.includes('ac unit')||name.includes('truss')||item.includes('truss')))return true;return false}
function builderLayerParent(type,root){if(isCurtainTrackRoot(root)||type==='curtainRail'||isCeilingDetailRoot(root))return ceilingLayer;if(typeof isPhysicalStageLayerRoot==='function'&&isPhysicalStageLayerRoot(root))return stageLayerGroup;if(typeof isLightingRigLayerRoot==='function'&&isLightingRigLayerRoot(root))return lightingLayerGroup;if(typeof isProductionLayerRoot==='function'&&isProductionLayerRoot(root))return productionLayerGroup;if(['wall','curvedWall','polyWall'].includes(type))return structuralWallLayer;if(type==='furniture'||(+root?.userData?.buildPhase||0)===5)return furnitureLayerGroup;if(['fixtureAsset'].includes(type))return furnitureLayerGroup;if(['artwork','plantAsset','sunsetLamp','barAsset','featureBlock','shelfArt','refPin'].includes(type))return artDecorLayerGroup;if(type==='ledScreen')return productionLayerGroup;return venue}
function snapRootToCeiling(root,announce=true){if(!isCeilingDetailRoot(root)&&!(root&&root.userData&&root.userData.builderType==='fixtureAsset'&&isCeilingMountedFixtureKind(root.userData.assetData&&root.userData.assetData.kind)))return false;const targetTop=ceilingMountReferenceY()-.012;if(root.userData&&root.userData.builderType==='polyWall'&&root.userData.polyWallData&&root.userData.polyWallData.style==='curtain'){const d=root.userData.polyWallData;d.ceilingMounted=true;d.topY=targetTop;root.position.y=0;rebuildPolylineWall(root);root.updateMatrixWorld(true);if(announce)flashEditor('Curtain track snapped flush to ceiling');return true}if(root.userData&&root.userData.builderType==='curtainRail'){const d=root.userData.assetData||{};const drop=Math.max(.55,+d.height||1.8);d.topY=targetTop;root.userData.assetData=d;root.position.y=Math.max(mainFloorLevel(),targetTop-drop);root.updateMatrixWorld(true);if(announce)flashEditor('Curtain rail snapped flush to ceiling');return true}root.updateMatrixWorld(true);const info=objectBoundsWorld(root);if(!info||!info.b)return false;const delta=(ceilingMountReferenceY()-.018)-info.b.max.y;if(Math.abs(delta)>1e-5){root.position.y+=delta;root.updateMatrixWorld(true)}if(announce)flashEditor('Snapped to ceiling');return true}
function normaliseFunctionalLayerParents(){builderObjects.forEach(root=>{if(!root||!root.userData)return;const parent=builderLayerParent(root.userData.builderType,root);if(parent&&root.parent!==parent)parent.add(root)})}
function normaliseCeilingMountedDetails(){builderObjects.forEach(root=>{const isCeilingFixture=root&&root.userData&&root.userData.builderType==='fixtureAsset'&&isCeilingMountedFixtureKind(root.userData.assetData&&root.userData.assetData.kind);if(!isCeilingDetailRoot(root)&&!isCeilingFixture)return;const parent=builderLayerParent(root.userData.builderType,root);if(parent&&root.parent!==parent)parent.add(root);snapRootToCeiling(root,false)});normaliseFunctionalLayerParents();scheduleCeilingRigGuideRebuild()}
let ceilingRigGuideFrame=0;
function clearCeilingRigGuideLines(){while(ceilingRigGuideLayer.children.length){const c=ceilingRigGuideLayer.children.pop();if(c.geometry)c.geometry.dispose();if(c.material)c.material.dispose()}ceilingRigGuideLayer.visible=false;markRenderDirty(120)}
function scheduleCeilingRigGuideRebuild(){clearCeilingRigGuideLines()}
function rebuildCeilingRigGuideLines(){clearCeilingRigGuideLines()}
function clearFloorBleed(root){const bleed=root&&root.userData&&root.userData.floorBleedMesh;if(!bleed)return;if(bleed.geometry)bleed.geometry.dispose();if(bleed.material)bleed.material.dispose();if(bleed.parent)bleed.parent.remove(bleed);delete root.userData.floorBleedMesh}
function syncFloorBleed(root){if(!root||!root.geometry||!root.userData)return;const isStatic=root.userData.builderType==='floorSurface',isDynamic=root.userData.builderType==='platform'&&isLowFloorRoot(root);if(!isStatic&&!isDynamic){clearFloorBleed(root);return}let bleed=root.userData.floorBleedMesh;if(!bleed){bleed=new THREE.Mesh(root.geometry.clone(),new THREE.MeshStandardMaterial({color:extractObjectColour(root),roughness:.92,side:THREE.DoubleSide}));bleed.userData.floorBleed=true;bleed.castShadow=false;bleed.receiveShadow=true;root.add(bleed);root.userData.floorBleedMesh=bleed}else{if(bleed.geometry)bleed.geometry.dispose();bleed.geometry=root.geometry.clone()}if(bleed.material&&bleed.material.color)bleed.material.color.set(extractObjectColour(root));bleed.position.set(0,-.004,0);bleed.rotation.set(0,0,0);if(isStatic&&root.geometry.type==='ShapeGeometry')bleed.scale.set(1,1,1);else if(isStatic)bleed.scale.set(1,1,1);else bleed.scale.set(1.02,1,1.02)}
function registerBuilderRoot(root,name,type,id=null){root.userData.dynamic=true;root.userData.lockedBase=false;root.userData.builderType=type;root.userData.editId=id||nextBuilderId();root.userData.editName=name||type;if(typeof currentBuildPhase!=='undefined'){root.userData.buildPhase=currentBuildPhase;root.userData.buildCategory=currentBuildCategory||'';root.userData.phaseLocked=!!phaseLocks[currentBuildPhase]}if(typeof phasePendingMeta!=='undefined'&&phasePendingMeta){root.userData.buildPhase=phasePendingMeta.phase;root.userData.buildCategory=phasePendingMeta.category||'';root.userData.buildItem=phasePendingMeta.item||'';root.userData.editName=phasePendingMeta.name||root.userData.editName;root.userData.phaseLocked=!!phaseLocks[phasePendingMeta.phase];phasePendingMeta=null}const layerParent=builderLayerParent(type,root);if(layerParent&&root.parent!==layerParent)layerParent.add(root);if(type==='platform'&&isLowFloorRoot(root))syncFloorBleed(root);builderObjects.push(root);if(!editorRoots.includes(root))editorRoots.push(root);const n=parseInt(String(root.userData.editId).replace(/\D/g,''),10);if(Number.isFinite(n))builderCounter=Math.max(builderCounter,n);if(typeof applyPhaseVisibilityToObject==='function')applyPhaseVisibilityToObject(root);if(typeof applyPerformanceSensitiveObjects==='function')applyPerformanceSensitiveObjects(root);if(typeof snapRootToCeiling==='function'&&(isCeilingDetailRoot(root)||(root.userData.builderType==='fixtureAsset'&&isCeilingMountedFixtureKind(root.userData.assetData&&root.userData.assetData.kind))))snapRootToCeiling(root,false);if(typeof scheduleCeilingRigGuideRebuild==='function')scheduleCeilingRigGuideRebuild();if(typeof markRenderDirty==='function')markRenderDirty();return root}
